  h1 { font-size: 28px; font-weight: 700; margin-bottom: 20px; color: #1a1a2e; }

  .input-row { display: flex; gap: 10px; margin-bottom: 20px; }
  .input-row input { flex: 1; padding: 12px 16px; border: 2px solid #e0e0e0; border-radius: 8px; font-size: 15px; outline: none; transition: border-color .2s; }
  .input-row input:focus { border-color: #4a90d9; }
  .input-row button { padding: 12px 24px; background: #4a90d9; color: #fff; border: none; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; transition: background .2s; }
  .input-row button:hover { background: #357abd; }

  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
  .filters button { padding: 8px 16px; border: 2px solid #e0e0e0; background: #fff; border-radius: 20px; font-size: 14px; cursor: pointer; transition: all .2s; }
  .filters button.active { background: #4a90d9; color: #fff; border-color: #4a90d9; }

  .todo-list { list-style: none; }
  .todo-list li { display: flex; align-items: center; gap: 14px; padding: 14px 0; border-bottom: 1px solid #f0f0f0; }
  .todo-list li:last-child { border-bottom: none; }
  .todo-list li.completed span { text-decoration: line-through; color: #999; }
  .todo-list li .checkbox { width: 22px; height: 22px; border: 2px solid #ccc; border-radius: 50%; flex-shrink: 0; cursor: pointer; transition: all .2s; display: flex; align-items: center; justify-content: center; }
  .todo-list li .checkbox.checked { background: #4a90d9; border-color: #4a90d9; }
  .todo-list li .checkbox.checked::after { content: '✓'; color: #fff; font-size: 14px; }
  .todo-list li .text { flex: 1; font-size: 15px; line-height: 1.4; }
  .todo-list li .delete { background: none; border: none; color: #ff4d4f; font-size: 18px; cursor: pointer; padding: 4px 8px; border-radius: 4px; transition: background .2s; }
  .todo-list li .delete:hover { background: #ffe0e0; }
  .empty { text-align: center; color: #aaa; padding: 30px 0; font-size: 15px; }
</style>
</head>
<body>
<div class="container">
  <h1>📝 Todo List</h1>
  <div class="input-row">
    <input type="text" id="todoInput" placeholder="Add a new todo..." autofocus>
    <button id="addBtn">Add</button>
  </div>
  <div class="filters">
    <button class="active" data-filter="all">All</button>
    <button data-filter="active">Active</button>
    <button data-filter="completed">Completed</button>
  </div>
  <ul class="todo-list" id="todoList"></ul>
</div>

<script>
  (function () {
    const STORAGE_KEY = 'todos';
    const todos = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
    const list = document.getElementById('todoList');
    const input = document.getElementById('todoInput');
    const addBtn = document.getElementById('addBtn');
    const filters = document.querySelectorAll('.filters button');
    let filter = 'all';

    function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); }

    function addTodo(text) {
      if (!text.trim()) return;
      todos.unshift({ id: Date.now(), text: text.trim(), completed: false });
      save(); render();
    }

    function toggleTodo(id) {
      const t = todos.find(x => x.id === id);
      if (t) { t.completed = !t.completed; save(); render(); }
    }

    function deleteTodo(id) {
      todos.splice(todos.findIndex(x => x.id === id), 1);
      save(); render();
    }

    function render() {
      list.innerHTML = '';
      const filtered = filter === 'all' ? todos : todos.filter(t => t.completed === (filter === 'completed'));
      if (filtered.length === 0) {
        list.innerHTML = '<li class="empty">No todos here yet</li>';
        return;
      }
      filtered.forEach(t => {
        const li = document.createElement('li');
        if (t.completed) li.classList.add('completed');
        li.innerHTML = '<span class="checkbox ' + (t.completed ? 'checked' : '') + '" onclick="toggleTodo(' + t.id + ')"></span><span class="text">' + escapeHtml(t.text) + '</span><button class="delete" onclick="deleteTodo(' + t.id + ')">×</button>';
        list.appendChild(li);
      });
    }

    function escapeHtml(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

    addBtn.addEventListener('click', () => addTodo(input.value));
    input.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(input.value); });
    filters.forEach(btn => btn.addEventListener('click', () => { filter = btn.dataset.filter; filters.forEach(b => b.classList.remove('active')); btn.classList.add('active'); render(); }));
    render();
  })();
</script>
</body>
</html>"}
